-- v0.6.1 git archive, virtual data from tagged physical-flow fixture.
PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE assistant_attachments(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES assistant_threads(id),user_id TEXT NOT NULL,upload_id TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,mime TEXT NOT NULL,kind TEXT NOT NULL,sha256 TEXT NOT NULL,metadata TEXT NOT NULL,bytes BLOB,extracted_text TEXT,image_pages TEXT,created_at TEXT NOT NULL,deleted_at TEXT,UNIQUE(user_id,upload_id));
CREATE TABLE assistant_audit(id INTEGER PRIMARY KEY,user_id TEXT NOT NULL,thread_id TEXT,tool TEXT NOT NULL,state TEXT NOT NULL,document TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE assistant_message_attachments(message_id TEXT NOT NULL REFERENCES assistant_messages(id) ON DELETE CASCADE,attachment_id TEXT NOT NULL REFERENCES assistant_attachments(id),PRIMARY KEY(message_id,attachment_id));
CREATE TABLE assistant_messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES assistant_threads(id),role TEXT NOT NULL,text TEXT NOT NULL,document TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE assistant_previews(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES assistant_threads(id),user_id TEXT NOT NULL,session_binding TEXT NOT NULL,expires_at INTEGER NOT NULL,digest TEXT NOT NULL,document TEXT NOT NULL,result TEXT);
CREATE TABLE assistant_runs(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES assistant_threads(id),user_id TEXT NOT NULL,state TEXT NOT NULL,document TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE assistant_threads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,title TEXT NOT NULL,document TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE business_audit(id INTEGER PRIMARY KEY,at TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,source TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,record_id INTEGER,document TEXT NOT NULL);
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, notes TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE flow_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL CHECK(kind IN ('arrival','task','production','delivery')),number TEXT NOT NULL UNIQUE,date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','confirmed','cancelled','reversed')),version INTEGER NOT NULL DEFAULT 1,document TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE flow_file_uses(hash TEXT PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES flow_documents(id));
CREATE TABLE flow_previews(id TEXT PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES flow_documents(id),actor_id TEXT NOT NULL,session_binding TEXT NOT NULL,expires_at INTEGER NOT NULL,digest TEXT NOT NULL,document TEXT NOT NULL);
CREATE TABLE flow_receipt_keys(supplier_id INTEGER NOT NULL REFERENCES suppliers(id),reference TEXT NOT NULL,document_id INTEGER NOT NULL REFERENCES flow_documents(id),PRIMARY KEY(supplier_id,reference));
CREATE TABLE flow_refs(document_id INTEGER NOT NULL REFERENCES flow_documents(id),customer_id INTEGER REFERENCES customers(id),supplier_id INTEGER REFERENCES suppliers(id),product_id INTEGER REFERENCES products(id),order_id INTEGER REFERENCES orders(id),order_line_id INTEGER REFERENCES order_lines(id),purchase_id INTEGER REFERENCES purchases(id),purchase_line_id INTEGER REFERENCES purchase_lines(id),stock_id INTEGER REFERENCES stock_items(id),task_id INTEGER REFERENCES flow_documents(id));
CREATE TABLE flow_sources(id TEXT PRIMARY KEY,file_name TEXT NOT NULL,hash TEXT NOT NULL,format TEXT NOT NULL,bytes BLOB NOT NULL,document TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE import_executions(id TEXT PRIMARY KEY,preview_id TEXT NOT NULL UNIQUE,source_id TEXT NOT NULL UNIQUE,file_hash TEXT NOT NULL,fingerprint TEXT NOT NULL,order_id INTEGER REFERENCES orders(id) ON DELETE SET NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,document TEXT NOT NULL);
CREATE TABLE import_previews(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,revision INTEGER NOT NULL,actor_id TEXT NOT NULL,expires_at TEXT NOT NULL,digest TEXT NOT NULL,document TEXT NOT NULL);
CREATE TABLE operation_requests(kind TEXT NOT NULL,request_id TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,PRIMARY KEY(kind,request_id));
CREATE TABLE order_extensions(order_id INTEGER PRIMARY KEY REFERENCES orders(id),document TEXT NOT NULL);
CREATE TABLE order_line_extensions(line_id INTEGER PRIMARY KEY REFERENCES order_lines(id) ON DELETE CASCADE,document TEXT NOT NULL);
CREATE TABLE order_lines(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id INTEGER NOT NULL REFERENCES products(id), product_name TEXT NOT NULL, specification TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0));
CREATE TABLE orders(id INTEGER PRIMARY KEY, number TEXT UNIQUE NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), customer_name TEXT NOT NULL, order_date TEXT NOT NULL, delivery_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('草稿','已确认','生产中','待发货','已发货','已取消')), notes TEXT NOT NULL, costs_json TEXT, total_cents INTEGER NOT NULL CHECK(total_cents>=0), version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE permanent_delete_previews(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,session_binding TEXT NOT NULL,expires_at INTEGER NOT NULL,digest TEXT NOT NULL,document TEXT NOT NULL,result TEXT);
CREATE TABLE permanent_record_deletions(entity TEXT NOT NULL,record_id INTEGER NOT NULL,deleted_at TEXT NOT NULL,actor_id TEXT NOT NULL,label TEXT NOT NULL,PRIMARY KEY(entity,record_id));
CREATE TABLE product_extensions(product_id INTEGER PRIMARY KEY REFERENCES products(id),document TEXT NOT NULL);
CREATE TABLE "products"(id INTEGER PRIMARY KEY,name TEXT NOT NULL,length REAL CHECK(length IS NULL OR (length>0 AND length<=10000)),width REAL CHECK(width IS NULL OR (width>0 AND width<=10000)),height REAL CHECK(height IS NULL OR (height>0 AND height<=10000)),dimension_unit TEXT CHECK(dimension_unit IS NULL OR dimension_unit IN ('mm','cm')),material TEXT NOT NULL DEFAULT '',flute TEXT NOT NULL DEFAULT '',requirements TEXT NOT NULL DEFAULT '',price_cents INTEGER NOT NULL DEFAULT 0 CHECK(price_cents>=0),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,CHECK(dimension_unit IS NULL OR dimension_unit='mm' OR (COALESCE(length,0)<=1000 AND COALESCE(width,0)<=1000 AND COALESCE(height,0)<=1000)));
CREATE TABLE purchase_lines(id INTEGER PRIMARY KEY,purchase_id INTEGER NOT NULL REFERENCES purchases(id),stock_item_id INTEGER REFERENCES stock_items(id),document TEXT NOT NULL,quantity_units INTEGER NOT NULL CHECK(quantity_units>0),received_units INTEGER NOT NULL DEFAULT 0 CHECK(received_units>=0));
CREATE TABLE purchase_receipts(id TEXT PRIMARY KEY,purchase_id INTEGER NOT NULL REFERENCES purchases(id),reference TEXT NOT NULL,date TEXT NOT NULL,document TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(purchase_id,reference));
CREATE TABLE purchases(id INTEGER PRIMARY KEY,number TEXT NOT NULL UNIQUE,supplier_id INTEGER NOT NULL REFERENCES suppliers(id),supplier_name TEXT NOT NULL,customer_order_id INTEGER REFERENCES orders(id),order_date TEXT NOT NULL,expected_date TEXT,status TEXT NOT NULL CHECK(status IN ('待订货','已订货','已取消')),notes TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE record_lifecycle(entity TEXT NOT NULL,record_id INTEGER NOT NULL,archived_at TEXT NOT NULL,actor_id TEXT NOT NULL,PRIMARY KEY(entity,record_id));
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE stock_items(id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('raw','finished')),unit TEXT NOT NULL,document TEXT NOT NULL,product_id INTEGER REFERENCES products(id),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE stock_movement_revisions(id INTEGER PRIMARY KEY,movement_id TEXT NOT NULL,item_id INTEGER NOT NULL,at TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,reason TEXT NOT NULL,before_document TEXT NOT NULL,after_document TEXT);
CREATE TABLE stock_movements(id TEXT PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES stock_items(id),action TEXT NOT NULL CHECK(action IN ('in','out','adjust','purchase')),delta_units INTEGER NOT NULL,before_units INTEGER NOT NULL CHECK(before_units>=0),after_units INTEGER NOT NULL CHECK(after_units>=0),source_kind TEXT NOT NULL,source_id TEXT,purchase_line_id INTEGER REFERENCES purchase_lines(id),customer_order_id INTEGER REFERENCES orders(id),date TEXT NOT NULL,notes TEXT NOT NULL,actor_id TEXT NOT NULL,actor_name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE suppliers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,contact TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,notes TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX assistant_attachments_owner ON assistant_attachments(user_id,thread_id);
CREATE INDEX assistant_messages_thread ON assistant_messages(thread_id,created_at);
CREATE INDEX business_audit_action ON business_audit(action);
CREATE INDEX flow_documents_kind ON flow_documents(kind,status);
CREATE INDEX flow_refs_document ON flow_refs(document_id);
CREATE INDEX flow_refs_order ON flow_refs(order_id);
CREATE INDEX flow_refs_order_line ON flow_refs(order_line_id);
CREATE INDEX flow_refs_task ON flow_refs(task_id);
CREATE INDEX import_fingerprint_lookup ON import_executions(fingerprint);
CREATE INDEX import_hash_lookup ON import_executions(file_hash);
CREATE UNIQUE INDEX import_live_file_unique ON import_executions(file_hash) WHERE order_id IS NOT NULL;
CREATE INDEX import_order_lookup ON import_executions(order_id);
CREATE INDEX order_lines_order ON order_lines(order_id);
CREATE INDEX order_lines_product ON order_lines(product_id);
CREATE INDEX orders_filter ON orders(customer_id,order_date,status);
CREATE INDEX purchase_lines_order ON purchase_lines(purchase_id);
CREATE INDEX purchase_receipts_purchase ON purchase_receipts(purchase_id);
CREATE INDEX purchases_order ON purchases(customer_order_id);
CREATE INDEX purchases_supplier ON purchases(supplier_id);
CREATE INDEX stock_movement_revisions_item ON stock_movement_revisions(item_id);
CREATE INDEX stock_movement_revisions_movement ON stock_movement_revisions(movement_id);
CREATE INDEX stock_movements_item ON stock_movements(item_id,created_at);
CREATE INDEX stock_movements_source ON stock_movements(source_kind,source_id);
COMMIT;
PRAGMA foreign_keys=ON;
